//! Minimal re-implementation of the pieces of the C++ `indicators`
//! library used by test2: `ProgressBar` and `Percentage`.

/// A simple text progress bar: `[=====>    ] 75.0%`
pub struct ProgressBar {
    progress: f64,
    total: f64,
    width: usize,
}

impl ProgressBar {
    pub fn new() -> Self {
        ProgressBar {
            progress: 0.0,
            total: 100.0,
            width: 50,
        }
    }

    pub fn set_progress(&mut self, progress: f64) {
        self.progress = progress;
    }

    pub fn set_total(&mut self, total: f64) {
        self.total = total;
    }

    pub fn set_width(&mut self, width: usize) {
        self.width = width;
    }

    /// Fraction of the bar that is complete, clamped to [0, 1].
    fn fraction(&self) -> f64 {
        if self.total <= 0.0 {
            return 0.0;
        }
        (self.progress / self.total).clamp(0.0, 1.0)
    }

    /// Renders `[=====>    ] 75.0%`.
    pub fn str(&self) -> String {
        let fraction = self.fraction();
        // Number of fully filled cells (floor), matching the C++ behavior.
        let filled = (fraction * self.width as f64) as usize;
        let mut bar = String::with_capacity(self.width + 8);
        bar.push('[');
        if filled >= self.width {
            bar.push_str(&"=".repeat(self.width));
        } else {
            bar.push_str(&"=".repeat(filled));
            bar.push('>');
            bar.push_str(&" ".repeat(self.width - filled - 1));
        }
        bar.push(']');
        bar.push(' ');
        bar.push_str(&Percentage::new(fraction as f32).str());
        bar
    }
}

/// Percentage value rendered as `75.0%` (one decimal place).
pub struct Percentage {
    value: f32,
}

impl Percentage {
    /// `value` is a fraction in [0, 1]; 0.75 renders as `75.0%`.
    pub fn new(value: f32) -> Self {
        Percentage { value }
    }

    pub fn str(&self) -> String {
        format!("{:.1}%", self.value * 100.0)
    }
}

